#!/usr/bin/env python3
"""Recount the actual curated files without rebuilding or overwriting their wording."""
from pathlib import Path
import json,csv,io,datetime,collections
R=Path(__file__).resolve().parents[1]
load=lambda p:json.loads((R/p).read_text())
words=load('data/words.json');dictionary=load('data/dictionary.json');examples=load('data/examples.json');old=load('data/coverage.json');reviews=load('research/review-status.json') if (R/'research/review-status.json').exists() else {}
now=datetime.datetime.now(datetime.timezone.utc).isoformat();complete=all(reviews.get(k,{}).get('status')=='passed' for k in ['stability','molly','content']);categories={str(l):{'total':sum(w['level']==l for w in words),'cards':sum(w['level']==l and w['id'] in dictionary for w in words),'examples':sum(w['level']==l and w['id'] in examples for w in words)} for l in [1,2,3]}
coverage={'updatedAt':now,'state':'complete-reviewed' if complete else 'content-complete-reviewing','total':len(words),'cards':len(dictionary),'examples':len(examples),'dictionaryCards':sum(d.get('sourceType')!='study-note' for d in dictionary.values()),'studyNotes':sum(d.get('sourceType')=='study-note' for d in dictionary.values()),'remaining':len(words)-len(dictionary),'examplesRemaining':len(words)-len(examples),'new2027':{'total':sum(w['new2027'] for w in words),'cards':sum(w['new2027'] and w['id'] in dictionary for w in words),'examples':sum(w['new2027'] and w['id'] in examples for w in words)},'categories':categories,'sourcePagesCached':old.get('sourcePagesCached'),'pendingLemmaPages':0,'needsLemmaExplanation':0,'errors':[],'editorialStatus':'All word/example pairs independently reviewed; see QA.md.' if complete else 'All explanations and examples present; independent review and corrections in progress.','officialListVerified':False}
(R/'data/coverage.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2)+'\n')
s=io.StringIO();out=csv.writer(s);out.writerow(['id','word','category','new_2027','explanation_status','example_status','independent_review','source'])
for w in words:
 d=dictionary.get(w['id']);e=examples.get(w['id']);out.writerow([w['id'],w['word'],['','One Bee','Two Bee','Three Bee'][w['level']],'yes' if w['new2027'] else 'no','original_study_note' if d and d.get('sourceType')=='study-note' else 'attributed_dictionary' if d else 'missing',e.get('type','missing') if e else 'missing','complete' if complete else 'in_progress',(d or {}).get('source','')])
(R/'WORD_CHECKLIST.csv').write_text(s.getvalue())
text=f"# Molly’s Word Journal — work tracker\n\nLast checkpoint: {now}\n\nState: **{coverage['state']}**. Counts below come from the saved records.\n\n| Category | Explanations | Examples | Words |\n| --- | ---: | ---: | ---: |\n"
for l in [1,2,3]:
 c=categories[str(l)];text+=f"| {['','One Bee','Two Bee','Three Bee'][l]} | {c['cards']} | {c['examples']} | {c['total']} |\n"
text+=f"\nAll **{len(dictionary):,} explanations** and **{len(examples):,} example sentences** are saved. All **505 explicitly new 2027 words** are included. Stable IDs preserve existing progress.\n\n## Review checkpoints\n\n"
for k in ['stability','molly','content']:
 v=reviews.get(k,{});text+=f"- **{k.title()}: {v.get('status','in progress')}**. {v.get('summary','Independent checks and fixes are underway.')}\n"
text+="\n## Files and safe continuation\n\n- `WORD_CHECKLIST.csv`: one row per spelling, with source and completion status.\n- `PROGRESS_LOG.jsonl`: durable import and review checkpoints.\n- `data/study-notes.json` and `data/example-batches`: curated wording, with stable word IDs.\n- `research/*review*.md` and keyed issue JSONs: independent review evidence and resolutions (local, ignored by Git).\n- `scripts/apply-content-review.py`: reapplies saved corrections; `scripts/merge-examples.mjs`: merges and validates sentences; `scripts/update-progress.py`: recounts without rewriting content.\n- Cached dictionary source batches remain in ignored `research/dictionary`. No new network import is needed. After any deliberate reimport, rerun the correction/merge scripts and data checks; the raw importer alone does not preserve all editorial choices.\n\n## Scope and remaining source limitations\n\nPublished version: https://emilystat.github.io/molly-champions-journal/ . Molly’s existing websites are unchanged. This is the 4,115-word mixed-year linked collection, not a reconciled official 4,000-word 2027 list. Computer-voice fallback is labelled; referenced Google recordings and rare-word pronunciations have not all been independently verified. These source limitations are separate from completed explanation/example coverage.\n"
(R/'WORK_TRACKER.md').write_text(text)
with (R/'PROGRESS_LOG.jsonl').open('a') as stream:stream.write(json.dumps({k:coverage[k] for k in ['updatedAt','state','cards','examples','remaining','examplesRemaining']})+'\n')
print(json.dumps({k:coverage[k] for k in ['state','cards','examples','remaining','examplesRemaining']}))
